import{_ as e,o as d,c as o,ag as a}from"./chunks/framework.CZxGLIO_.js";const p=JSON.parse('{"title":"任务配置与执行","description":"选择常驻或定时任务，理解命令模式、Cron、重启策略及编辑限制。","frontmatter":{"title":"任务配置与执行","description":"选择常驻或定时任务，理解命令模式、Cron、重启策略及编辑限制。"},"headers":[],"relativePath":"docs/rooster/tasks/index.md","filePath":"docs/rooster/tasks/index.md"}'),r={name:"docs/rooster/tasks/index.md"};function c(l,t,h,n,i,s){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="任务配置与执行" tabindex="-1">任务配置与执行 <a class="header-anchor" href="#任务配置与执行" aria-label="Permalink to &quot;任务配置与执行&quot;">​</a></h1><p>建议先创建停用任务，手动运行一次并检查日志，再启用自动运行。“启用”表示调度或守护开启，“运行”表示当前有命令执行，两者是独立状态。</p><h2 id="选择任务类型" tabindex="-1">选择任务类型 <a class="header-anchor" href="#选择任务类型" aria-label="Permalink to &quot;选择任务类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>行为</th><th>常驻 <code>resident</code></th><th>定时 <code>scheduled</code></th></tr></thead><tbody><tr><td>适合</td><td>开发服务、长时间运行的工作进程</td><td>定期检查、同步、脚本</td></tr><tr><td>启用</td><td>启动守护</td><td>注册 Cron</td></tr><tr><td>停用</td><td>停止守护，请求终止其管理的执行</td><td>取消未来触发，已有执行继续</td></tr><tr><td>手动运行</td><td>可以，停用时也可以</td><td>可以，停用时也可以</td></tr></tbody></table><p>常驻任务不是用来把短命令强行循环执行的；短命令周期运行通常应使用定时任务。</p><h2 id="shell-与直接执行" tabindex="-1">Shell 与直接执行 <a class="header-anchor" href="#shell-与直接执行" aria-label="Permalink to &quot;Shell 与直接执行&quot;">​</a></h2><ul><li><code>shell</code>：支持管道、重定向和 shell 语法，例如 <code>echo ready</code>；可选择自定义 shell。</li><li><code>exec</code>：<code>command</code> 填可执行程序，<code>arguments</code> 填独立参数，不要把整条 shell 命令塞进程序名。</li></ul><p>例如运行开发服务时，可将模式设为 <code>exec</code>，程序填 <code>/absolute/path/to/pnpm</code>，参数填 <code>[&quot;dev&quot;]</code>，工作目录填项目绝对路径。此处数组展示参数结构。</p><p><code>workingDir</code> 留空会继承 Rooster 的工作目录。任务环境变量覆盖继承的缓存环境；命令依赖 PATH、解释器或包管理器时，优先使用绝对路径。终端里能运行不代表托盘启动后的环境完全相同。</p><h2 id="cron-与重叠策略" tabindex="-1">Cron 与重叠策略 <a class="header-anchor" href="#cron-与重叠策略" aria-label="Permalink to &quot;Cron 与重叠策略&quot;">​</a></h2><p>五字段顺序为「分 时 日 月 星期」，不是带秒的六字段表达式。</p><table tabindex="0"><thead><tr><th>表达式</th><th>用途</th></tr></thead><tbody><tr><td><code>*/15 * * * *</code></td><td>每 15 分钟</td></tr><tr><td><code>0 3 * * *</code></td><td>每天 03:00</td></tr><tr><td><code>0 9 * * 1-5</code></td><td>周一至周五 09:00</td></tr><tr><td><code>CRON_TZ=Asia/Shanghai 0 9 * * *</code></td><td>按上海时区每天 09:00</td></tr></tbody></table><p>默认使用 Rooster 进程所在时区，也支持 <code>@hourly</code> 等描述符。创建后查看控制台预览的未来五次触发时间。</p><p><code>overlapPolicy</code> 默认 <code>skip</code>，已有执行时阻止新的重叠执行；<code>parallel</code> 允许并行。会修改同一文件或目标数据的任务应先确认能否并发。手动运行遇到重叠冲突会返回 <code>409</code>，不会排队等待。</p><h2 id="常驻重启策略" tabindex="-1">常驻重启策略 <a class="header-anchor" href="#常驻重启策略" aria-label="Permalink to &quot;常驻重启策略&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置</th><th>含义</th></tr></thead><tbody><tr><td><code>restartPolicy: on_failure</code></td><td>默认，失败后重启</td></tr><tr><td><code>restartPolicy: always</code></td><td>自动重启</td></tr><tr><td><code>restartPolicy: never</code></td><td>不自动重启</td></tr><tr><td><code>maxRetries</code></td><td>连续失败上限，省略或 <code>0</code> 使用 <code>3</code></td></tr><tr><td><code>minRunSeconds</code></td><td>最短正常运行时长，省略或 <code>0</code> 使用 <code>10</code> 秒</td></tr></tbody></table><p>非零退出码或运行时间短于 <code>minRunSeconds</code> 都可能被守护器视为失败。一次很快退出且退出码为 0 的执行，历史状态仍可能是成功，但守护器会按短运行失败处理并重试。达到连续失败上限会停用任务；<code>maxRetries=0</code> 不代表无限重试。</p><h2 id="停止、编辑与删除" tabindex="-1">停止、编辑与删除 <a class="header-anchor" href="#停止、编辑与删除" aria-label="Permalink to &quot;停止、编辑与删除&quot;">​</a></h2><p>编辑入口始终可打开，启用或运行中显示只读配置。修改步骤是：停用任务，等待或停止活动执行，确认没有运行，再重新打开编辑并保存。删除也有相同前置条件。</p><p>停用定时任务不会停止当前执行；停止某次定时执行也不会停用未来调度。停止启用中的常驻执行会同时停用自动守护。手动启动的执行可能需要单独停止。</p><h2 id="实例级资源限制" tabindex="-1">实例级资源限制 <a class="header-anchor" href="#实例级资源限制" aria-label="Permalink to &quot;实例级资源限制&quot;">​</a></h2><p>可在启动时设置以下环境变量，<code>0</code> 或未设置表示不限制：</p><table tabindex="0"><thead><tr><th>变量</th><th>作用</th></tr></thead><tbody><tr><td><code>ROOSTER_MAX_CONCURRENT</code></td><td>实例同时活动或启动的执行数上限</td></tr><tr><td><code>ROOSTER_MAX_PER_TASK</code></td><td>单任务并发执行上限</td></tr><tr><td><code>ROOSTER_EXECUTION_TIMEOUT</code></td><td>所有类型执行的超时，例如 <code>30m</code></td></tr></tbody></table><p>达到并发上限的手动请求返回 <code>409</code>，不进入等待队列。超时记录为失败，错误含 <code>context deadline exceeded</code>；对常驻服务设置统一超时前应考虑是否符合预期。</p><hr><p>核对日期：2026-11-15；依据当前源码：<a href="https://github.com/leancodebox/rooster/blob/96c86ae62c530da51cd6cd0f7b37b3d6fb7e89be/internal/httpapi/agent/references/api.md" target="_blank" rel="noreferrer">任务字段与语义</a> · <a href="https://github.com/leancodebox/rooster/blob/96c86ae62c530da51cd6cd0f7b37b3d6fb7e89be/internal/roosterapp/limits.go" target="_blank" rel="noreferrer">实例限制实现</a>。</p>',26)])])}const u=e(r,[["render",c]]);export{p as __pageData,u as default};
